ON CONFLICT (kok_ar) DO UPDATE SET
    kok_tr = EXCLUDED.kok_tr,
    kok_anlami = CASE
        WHEN kokler.kok_anlami IS NOT NULL AND length(kokler.kok_anlami) > 0 THEN kokler.kok_anlami
        ELSE EXCLUDED.kok_anlami
    END;

SELECT setval('kokler_id_seq', (SELECT COALESCE(MAX(id), 1) FROM kokler));

