) AS v(sure_id, ayet_no, kelime_no, metin_ar, metin_tr, kok_ar, vezin, metin_en)
JOIN ayetler a ON a.sure_id = v.sure_id AND a.ayet_no = v.ayet_no
LEFT JOIN kokler k ON k.kok_ar = v.kok_ar
ON CONFLICT (ayet_id, kelime_no) DO UPDATE SET
    metin_ar = EXCLUDED.metin_ar,
    kok_id = COALESCE(kelimeler.kok_id, EXCLUDED.kok_id),
    vezin = CASE WHEN kelimeler.vezin IS NOT NULL AND kelimeler.vezin <> '' THEN kelimeler.vezin ELSE EXCLUDED.vezin END,
    metin_tr = CASE WHEN kelimeler.metin_tr IS NOT NULL AND kelimeler.metin_tr <> '' THEN kelimeler.metin_tr ELSE EXCLUDED.metin_tr END,
    metin_en = COALESCE(kelimeler.metin_en, EXCLUDED.metin_en);

